package org.eclipse.rdf4j.sail.lucene;

import static org.assertj.core.api.Assertions.assertThat;

import java.util.Iterator;
import java.util.List;
import java.util.Set;
import java.util.concurrent.atomic.AtomicInteger;

import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.BindingSet;
import org.eclipse.rdf4j.query.algebra.BindingSetAssignment;
import org.eclipse.rdf4j.query.algebra.EmptySet;
import org.eclipse.rdf4j.query.algebra.QueryModelNode;
import org.eclipse.rdf4j.query.algebra.QueryRoot;
import org.eclipse.rdf4j.query.algebra.SingletonSet;
import org.eclipse.rdf4j.query.impl.ListBindingSet;
import org.junit.jupiter.api.Test;

class AbstractSearchQueryEvaluatorTest {

	@Test
	void unknownSourcesAreInstalledWithoutOpeningAnIterator() {
		BindingSet row = new ListBindingSet(List.of("x"), SimpleValueFactory.getInstance().createIRI("urn:result"));
		for (List<BindingSet> rows : List.of(List.of(row), List.<BindingSet>of())) {
			AtomicInteger opens = new AtomicInteger();
			Iterator<BindingSet> iterator = rows.iterator();
			BindingSetAssignment assignment = new BindingSetAssignment();
			assignment.setDeclaredBindingNames(Set.of("x"));
			assignment.setBindingSets(() -> {
				opens.incrementAndGet();
				return iterator;
			});
			QueryRoot root = new QueryRoot(new SingletonSet());
			evaluator(root).replaceQueryPatternsWithResults(assignment);
			assertThat(opens).hasValue(0);
			assertThat(root.getArg()).isSameAs(assignment);
			assertThat(assignment.getBindingSets()).containsExactlyElementsOf(rows);
		}
	}

	@Test
	void repeatableSourcesRetainEmptyRelationDetection() {
		BindingSet row = new ListBindingSet(List.of("x"), SimpleValueFactory.getInstance().createIRI("urn:result"));
		for (List<BindingSet> rows : List.of(List.of(row), List.<BindingSet>of())) {
			BindingSetAssignment assignment = new BindingSetAssignment();
			assignment.setBindingSets(rows);
			QueryRoot root = new QueryRoot(new SingletonSet());
			evaluator(root).replaceQueryPatternsWithResults(assignment);
			if (rows.isEmpty()) {
				assertThat(root.getArg()).isInstanceOf(EmptySet.class);
			} else {
				assertThat(root.getArg()).isSameAs(assignment);
			}
		}
	}

	private static AbstractSearchQueryEvaluator evaluator(QueryRoot root) {
		return new AbstractSearchQueryEvaluator() {
			@Override
			public QueryModelNode getParentQueryModelNode() {
				return root;
			}

			@Override
			public QueryModelNode removeQueryPatterns() {
				return root.getArg();
			}
		};
	}
}
